{
  "findings": [
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Microsoft may share your data with third‑party ad companies.",
      "stance": "risk",
      "quote": "Advertisers sometimes include their own or other advertising partners’ web beacons within their ads that we display, enabling them to set and read their own cookies."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Microsoft partners with Xandr and other third‑party ad companies to show ads.",
      "stance": "risk",
      "quote": "Microsoft partners with Xandr (a Microsoft Company) and third‑party ad companies to help provide some of our advertising services, and we also allow other third‑party ad companies to display advertisements on our sites."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Third‑party ad companies can place cookies on your device and track your online activity.",
      "stance": "risk",
      "quote": "These companies may place cookies on your devices and collect data about your online activities across websites or online services."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Microsoft may share collected data with internal and external partners, including Yahoo and Facebook.",
      "stance": "risk",
      "quote": "We may provide collected data to internal and external partners, including Xandr, other subsidiaries and affiliates, Yahoo, Facebook, or Trade Desk to help make sure the ads you see in our products and theirs, or on other sites, are more relevant to you."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Microsoft can turn off personalized ad sharing if a Global Privacy Control signal is received.",
      "stance": "mitigation",
      "quote": "Microsoft receives and responds to the Global Privacy Control (GPC) browser opt‑out signal in certain jurisdictions. Microsoft will turn off sharing your data with third parties for personalized ads and turn off the “Share my data with third parties for personalized ads” toggle if we receive a GPC signal from you when you visit our sites."
    }
  ]
}
